import random
import math

def run_trial(seed: int) -> dict:
    random.seed(seed)

    def gaussian_elimination(A):
        m, n = len(A), len(A[0])
        for i in range(m):
            max_row = i + sum(1 for j in range(i+1, m) if abs(A[j][i]) > abs(A[i][i]))
            A[i], A[max_row] = A[max_row], A[i]
            for j in range(i+1, m):
                factor = -A[j][i] / A[i][i]
                for k in range(n):
                    A[j][k] += factor * A[i][k]
        return A

    def matrix_multiplication(A, B):
        m, n, p = len(A), len(B), len(B[0])
        C = [[0] * p for _ in range(m)]
        for i in range(m):
            for j in range(p):
                for k in range(n):
                    C[i][j] += A[i][k] * B[k][j]
        return C

    def hypergeometric_coefficients(q, n):
        if q <= 0 or n <= 0:
            return []
        coeffs = [1]
        for i in range(1, n):
            coeff = (q - i + 1) / (i * (q + i))
            coeffs.append(coeff)
        return coeffs

    def q_difference_operator(k, n):
        if k <= 0 or n <= 0:
            return []
        q = random.randint(2, 5)
        coeffs = hypergeometric_coefficients(q, n)
        operator = [[0] * (n+1) for _ in range(n+1)]
        operator[0][0] = 1
        for i in range(1, n+1):
            operator[i][i-1] = -coeffs[i-1]
            operator[i][i] = q
        return operator

    def count_non_zero_coeffs(operator):
        count = 0
        for row in operator:
            for coeff in row:
                if coeff != 0:
                    count += 1
        return count

    n_values = [5, 10, 15, 20, 30, 40]
